# Generated by manage.py generate_test_cases.
from django.core.files.uploadedfile import SimpleUploadedFile

from bloomerp.models import File
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestRenameFileComponent(BloomerpComponentTestCase):
    """Tests function `rename_file` from `bloomerp/components/files/actions/rename.py`."""

    view_name = "components_files_rename"

    def get_test_scenarios(self) -> list[RequestScenario]:
        file = File.objects.create(
            name="Before.txt",
            file=SimpleUploadedFile("Before.txt", b"test content"),
            persisted=True,
            created_by=self.admin_user,
            updated_by=self.admin_user,
        )
        view_kwargs = {"file_id": file.pk}

        return [
            RequestScenario(
                name="render rename form for an admin",
                user=self.admin_user,
                view_kwargs=view_kwargs,
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        'name="name"' in response.content.decode()
                        and 'value="Before.txt"' in response.content.decode()
                    ),
                ),
            ),
            RequestScenario(
                name="rename a file as an admin",
                method="POST",
                user=self.admin_user,
                view_kwargs=view_kwargs,
                data={"name": "After.txt"},
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        response.headers.get("HX-Refresh") == "true"
                        and File.objects.filter(
                            pk=file.pk,
                            name="After.txt",
                            updated_by=self.admin_user,
                        ).exists()
                    ),
                ),
            ),
        ]
